const highlight = (code) => code.replace(/\/\/[^\n]*|'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|`(?:\\.|[^`\\])*`|\b(?:import|from|const|let|var|new|await|return|if|else|throw|async|function|class|true|false|null)\b|\b\d+\b/g, (token) => {
  const safe = token.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const type = token.startsWith('//') ? 'tok-comment' : /^['"`]/.test(token) ? 'tok-string' : /^\d/.test(token) ? 'tok-number' : 'tok-keyword';
  return `<span class="${type}">${safe}</span>`;
}).replace(/\n/g, '\n');
const snippet = (code) => `<pre><button class="code-copy" type="button" aria-label="Copy code">Copy</button><code>${highlight(code)}</code></pre>`;
const table = (head, rows) => `<table><thead><tr>${head.map((x) => `<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map((row) => `<tr>${row.map((x) => `<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const callout = (text, warning = false) => `<div class="callout${warning ? ' warning' : ''}">${text}</div>`;
